-- ============================================================================
-- Курс 238 — этап 3: семинарский блок + фикс таблицы. 2026-09-08.
-- 1) Страница 2462: таблице класс table-reboot (выводит её из-под табличного
--    «ребута» Moodle с высокой специфичностью — рамки рисуем сами).
-- 2) Форум 3895 «Семинар (в записи)» (cmid 13429): intro на классы.
-- 3) Пост 422133 (тема d=29292 «Открыть Семинар "Что такое каббала"»): на классы.
-- 4) Книга 965 (cmid 13428), глава 2264 «Правила семинара»: на классы.
-- Тексты дословно; шрифтовой мусор (Trebuchet/размеры) убран.
-- ============================================================================

CREATE TABLE IF NOT EXISTS _kab_bk20260908c_forum3895 AS SELECT * FROM mdl_forum WHERE id=3895;
CREATE TABLE IF NOT EXISTS _kab_bk20260908c_post422133 AS SELECT * FROM mdl_forum_posts WHERE id=422133;
CREATE TABLE IF NOT EXISTS _kab_bk20260908c_bookch2264 AS SELECT * FROM mdl_book_chapters WHERE id=2264;

-- 1) Таблица «Пять отрезков» — вывести из-под ребута
UPDATE mdl_page SET timemodified=UNIX_TIMESTAMP(),
  content=REPLACE(content, 'class="kab-table"', 'class="kab-table table-reboot"')
  WHERE id=2462;

-- 2) Форум 3895 «Семинар (в записи)»
UPDATE mdl_forum SET timemodified=UNIX_TIMESTAMP(), intro='<div class="kab-text">
<div class="kab-quote">По вторникам у нас ДЕНЬ СЕМИНАРОВ.</div>
<p><b>В уроках 1-5</b> будут выставляться <b>семинары в ЗАПИСИ</b>: вы смотрите видео учебного семинара и отвечаете на вопрос по теме урока.</p>
<p>Предварительно рекомендуем ознакомиться с <a href="https://edu.kabacademy.com/mod/book/view.php?id=13428" target="_blank" rel="noopener" class="kab-link">Правилами семинара</a>.</p>
<p>Приглашаем всех участвовать в этом познавательном мероприятии!</p>
</div>' WHERE id=3895;

-- 3) Первый пост темы 29292
